describe('README inputs from the #442 reviews', () => {
  const lf = (s: string): string => s.replace(/\r(?=\n)/g, '');
  it.each(cases.map(c => [c.title, c] as const))('%s', (_title, c) => {
    expect(parseWorkflowChecklistFromReadme(c.md).map(e => e.fileName)).toEqual(c.parse);
    expect(hasWorkflowChecklistSection(c.md)).toBe(c.has);
    if (c.rename) expect(lf(reconcileWorkflowChecklist(c.md, [c.rename], { move: true }).content)).toBe(c.move);
    expect(insertWorkflowChecklistEntries(c.md, [D])).toBe(c.ins);
    expect(parseWorkflowChecklistFromReadme(c.ins).some(e => e.fileName === D.fileName)).toBe(true);
    const added = c.ins.split('\n');
    // In a fence only when the section heading is fenced too, where v0.130.0 put it.
    expect(readmeFencedLines(added)[added.findIndex(l => l.includes(D.fileName))]).toBe(c.insFenced);
    for (const [file, result] of c.rem) expect(removeWorkflowFromReadme(c.md, file)).toEqual(result);
  });
});

